  ('ramayana-manas-uttarkanda-ramrajya-teachings-v1', 'aftermath', 1, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_UTTARKANDA_FRAMES_DB_V1","expectationId":"manas-uttar-kanda-bhakti-teachings","storyId":"ramayana-manas-uttarkanda-ramrajya-teachings-v1","sourceId":"ramcharitmanas-belvedere-fixed-scan","scanSha256":"6d570d531ebada1912f6e930212393fec2200765a0b731b73b8e7135ea0f70f2","kanda":"Uttarkanda","scanPagesInclusive":[1071,1130],"dohaRangeInclusive":[1,51],"secondaryLocator":"IITK Uttarkanda opening through doha 51"}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["rama","sita","bharata","lakshmana","shatrughna","hanuman","kaikeyi","kaushalya","sumitra","vasishtha","narada","vibhishana","sugriva","angada","shiva","parvati"],"places":["the sky above Ayodhya","Nandigrama","Ayodhya","Rama''s coronation hall","the Sarayu ghats","the mango grove outside Ayodhya"],"relationships":[{"target_kind":"story_cycle","target_id":"road-home","relationship":"continues_return_and_coronation_after","inverse_relationship":"continues_into_expression_specific_coronation","bidirectional":true},{"target_kind":"story_cycle","target_id":"later-reign","relationship":"provides_expression_specific_ideal_reign_for","inverse_relationship":"has_parallel_expression_telling","bidirectional":true},{"target_kind":"entity","target_id":"rama","relationship":"centres_on","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"entity","target_id":"hanuman","relationship":"establishes_continuing_service_of","inverse_relationship":"continues_service_in","bidirectional":true},{"target_kind":"story","target_id":"ramayana-manas-kakabhushundi-garuda-dialogue-v1","relationship":"precedes_closing_narration_frame","inverse_relationship":"follows_court_and_public_sequence","bidirectional":true}],"expressionScope":"ramcharitmanas"}'::jsonb),
